import csv
import json
import statistics
import math
from collections import defaultdict

def read_data(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        data = list(reader)
    # Type conversion
    for row in data:
        for k, v in row.items():
            if v == '': continue
            try:
                row[k] = float(v) if '.' in v else int(v)
            except ValueError:
                pass
    return data

def main():
    data = read_data('/app/benchmark/data.csv')

    # 1. KPIs
    cost_of_living_indices = [row['cost_of_living_index'] for row in data]
    median_coli = statistics.median(cost_of_living_indices)

    rent_to_salary_ratios = [row['rent_to_salary_ratio_pct'] for row in data]
    avg_rent_to_salary = sum(rent_to_salary_ratios) / len(rent_to_salary_ratios)

    purchasing_powers = [row['local_purchasing_power_index'] for row in data]
    pp_gap = max(purchasing_powers) - min(purchasing_powers)

    crisis_tiers = [row['cost_crisis_tier'] for row in data]
    max_tier = max(crisis_tiers)
    high_crisis_count = sum(1 for tier in crisis_tiers if tier == max_tier)

    inflation_rates = [row['annual_inflation_rate_2025_pct'] for row in data]
    avg_inflation = sum(inflation_rates) / len(inflation_rates)

    # 2. Executive Overview Details
    most_expensive = max(data, key=lambda x: x['cost_of_living_index'])['city']
    least_expensive = min(data, key=lambda x: x['cost_of_living_index'])['city']

    # 3. Regional Aggregation
    regions = defaultdict(list)
    for row in data:
        regions[row['region']].append(row)

    regional_stats = {}
    for region, cities in regions.items():
        regional_stats[region] = {
            'avg_coli': sum(c['cost_of_living_index'] for c in cities) / len(cities),
            'avg_rent': sum(c['rent_index'] for c in cities) / len(cities),
            'avg_pp': sum(c['local_purchasing_power_index'] for c in cities) / len(cities),
            'cities': cities
        }

    # Regional outliers (cost of living > 1 standard deviation from regional mean)
    outliers_html = ""
    for region, stats in regional_stats.items():
        if len(stats['cities']) > 2:
            colis = [c['cost_of_living_index'] for c in stats['cities']]
            mean = stats['avg_coli']
            stdev = statistics.stdev(colis)
            for c in stats['cities']:
                if abs(c['cost_of_living_index'] - mean) > stdev:
                    outliers_html += f"<li><strong>{c['city']}</strong> in {region}: COLI is {c['cost_of_living_index']:.1f} (Regional avg: {mean:.1f})</li>"

    # 4. Affordability
    # Top 10 burdened cities
    top_burdened = sorted(data, key=lambda x: x['rent_to_salary_ratio_pct'], reverse=True)[:10]

    # 5. Crisis Tier Profiling
    tiers = defaultdict(list)
    for row in data:
        tiers[row['cost_crisis_tier']].append(row)

    tier_stats = []
    for tier, cities in sorted(tiers.items()):
        label = cities[0]['crisis_label']
        tier_stats.append({
            'tier': tier,
            'label': label,
            'count': len(cities),
            'avg_coli': sum(c['cost_of_living_index'] for c in cities) / len(cities),
            'avg_rent_burden': sum(c['rent_to_salary_ratio_pct'] for c in cities) / len(cities),
            'avg_pp': sum(c['local_purchasing_power_index'] for c in cities) / len(cities)
        })

    # 6. Inflation & Oil Shock
    oil_exposure = defaultdict(list)
    for row in data:
        oil_exposure[row['oil_shock_exposure']].append(row)

    oil_stats = []
    for exposure, cities in oil_exposure.items():
